1	/**
2	 * Converts OpenAI tool format to Vercel AI SDK format
3	 */
4	
5	import type { ChatCompletionCreateParams } from "openai/resources/index.js";
6	
7	/**
8	 * Recursively transforms schemas to be OpenAI strict mode compatible:
9	 * - Adds additionalProperties: false to all object schemas
10	 * - Ensures all properties are listed in the required array
11	 */
12	function makeOpenAIStrictCompatible(schema: any): any {
13	  if (!schema || typeof schema !== "object") {
14	    return schema;
15	  }
16	
17	  const result = { ...schema };
18	
19	  if (result.type === "object") {
20	    result.additionalProperties = false;
21	
22	    if (result.properties) {
23	      const propertyKeys = Object.keys(result.properties);
24	      result.required = propertyKeys;
25	
26	      result.properties = Object.fromEntries(
27	        Object.entries(result.properties).map(([key, value]) => [
28	          key,
29	          makeOpenAIStrictCompatible(value),
30	        ]),
31	      );
32	    }
33	  }
34	
35	  if (result.items) {
36	    result.items = makeOpenAIStrictCompatible(result.items);
37	  }
38	
39	  if (result.anyOf) {
40	    result.anyOf = result.anyOf.map(makeOpenAIStrictCompatible);
41	  }
42	
43	  if (result.oneOf) {
44	    result.oneOf = result.oneOf.map(makeOpenAIStrictCompatible);
45	  }
46	
47	  if (result.allOf) {
48	    result.allOf = result.allOf.map(makeOpenAIStrictCompatible);
49	  }
50	
51	  return result;
52	}
53	
54	/**
55	 * Converts OpenAI tool format to Vercel AI SDK format.
56	 *
57	 * OpenAI format: { type: "function", function: { name, description, parameters: JSONSchema } }
58	 * Vercel format: { [toolName]: { description, parameters: aiJsonSchema(JSONSchema) } }
59	 *
60	 * @param openaiTools - Array of OpenAI tools or undefined
61	 * @returns Object with tool names as keys, or undefined if no tools
62	 */
63	export async function convertToolsToVercelFormat(
64	  openaiTools?: ChatCompletionCreateParams["tools"],
65	): Promise<Record<string, any> | undefined> {
66	  if (!openaiTools || openaiTools.length === 0) {
67	    return undefined;
68	  }
69	
70	  const { jsonSchema: aiJsonSchema } = await import("ai");
71	
72	  const vercelTools: Record<string, any> = {};
73	  for (const tool of openaiTools) {
74	    if (tool.type === "function") {
75	      const parameters = makeOpenAIStrictCompatible(
76	        tool.function.parameters ?? { type: "object", properties: {} },
77	      );
78	      vercelTools[tool.function.name] = {
79	        description: tool.function.description,
80	        parameters: aiJsonSchema(parameters),
81	      };
82	    }
83	  }
84	
85	  return Object.keys(vercelTools).length > 0 ? vercelTools : undefined;
86	}
