13	export function chatChunk(options: {
14	  content: string | null | undefined;
15	  model: string;
16	  finish_reason?: ChatCompletionChunk.Choice["finish_reason"];
17	  id?: string | null;
18	  usage?: CompletionUsage;
19	}): ChatCompletionChunk {
20	  return {
21	    choices: [
22	      {
23	        delta: {
24	          content: options.content,
25	          role: "assistant",
26	        },
27	        finish_reason: options.finish_reason ?? "stop",
28	        index: 0,
29	        logprobs: null,
30	      },
31	    ],
32	    usage: options.usage,
33	    created: Date.now(),
34	    id: options.id ?? "",
35	    model: options.model,
36	    object: "chat.completion.chunk",
37	  };
38	}
39	
40	export function usageChatChunk(options: {
41	  model: string;
42	  id?: string | null;
43	  usage?: CompletionUsage;
44	}): ChatCompletionChunk {
45	  return {
46	    choices: [],
47	    usage: options.usage,
48	    created: Date.now(),
49	    id: options.id ?? "",
50	    model: options.model,
51	    object: "chat.completion.chunk",
52	  };
53	}
