155	export function customFetch(
156	  requestOptions: RequestOptions | undefined,
157	): typeof patchedFetch {
158	  if (process.env.FEATURE_FLAG_DISABLE_CUSTOM_FETCH) {
159	    return patchedFetch;
160	  }
161	
162	  function letRequestOptionsOverrideAuthHeaders(init: any): any {
163	    if (!init || !init.headers || !requestOptions || !requestOptions.headers) {
164	      return init;
165	    }
166	
167	    // Check if custom Authorization or x-api-key headers are provided
168	    const hasCustomAuth =
169	      requestOptions.headers["Authorization"] ||
170	      requestOptions.headers["authorization"];
171	    const hasCustomXApiKey =
172	      requestOptions.headers["x-api-key"] ||
173	      requestOptions.headers["X-Api-Key"];
174	
175	    // Remove default auth headers if custom ones are provided
176	    if (hasCustomAuth || hasCustomXApiKey) {
177	      if (init.headers instanceof Headers) {
178	        if (hasCustomAuth) {
179	          init.headers.delete("Authorization");
180	        }
181	        if (hasCustomXApiKey) {
182	          init.headers.delete("x-api-key");
183	        }
184	      } else if (Array.isArray(init.headers)) {
185	        init.headers = init.headers.filter((header: [string, string]) => {
186	          const headerLower = (header[0] ?? "").toLowerCase();
187	          if (hasCustomAuth && headerLower === "authorization") return false;
188	          if (hasCustomXApiKey && headerLower === "x-api-key") return false;
189	          return true;
190	        });
191	      } else if (typeof init.headers === "object") {
192	        if (hasCustomAuth) {
193	          delete init.headers["Authorization"];
194	          delete init.headers["authorization"];
195	        }
196	        if (hasCustomXApiKey) {
197	          delete init.headers["x-api-key"];
198	          delete init.headers["X-Api-Key"];
199	        }
200	      }
201	    }
202	    return init;
203	  }
204	
205	  return (req: URL | string | Request, init?: any) => {
206	    init = letRequestOptionsOverrideAuthHeaders(init);
207	    if (typeof req === "string" || req instanceof URL) {
208	      return fetchwithRequestOptions(req, init, requestOptions);
209	    } else {
210	      return fetchwithRequestOptions(req.url, init, requestOptions);
211	    }
212	  };
213	}
