7	
8	describe("convertVercelStreamPart", () => {
9	  const options = { model: "gpt-4o-mini" };
10	
11	  test("converts text-delta to chat chunk", () => {
12	    const part: VercelStreamPart = {
13	      type: "text-delta",
14	      textDelta: "Hello",
15	    };
16	
17	    const result = convertVercelStreamPart(part, options);
18	
19	    expect(result).not.toBeNull();
20	    expect(result?.object).toBe("chat.completion.chunk");
21	    expect(result?.model).toBe("gpt-4o-mini");
22	    expect(result?.choices).toHaveLength(1);
23	    expect(result?.choices[0].delta.content).toBe("Hello");
24	  });
25	
26	  test("converts reasoning to chat chunk", () => {
27	    const part: VercelStreamPart = {
28	      type: "reasoning",
29	      textDelta: "Let me think...",
30	    };
31	
32	    const result = convertVercelStreamPart(part, options);
33	
34	    expect(result).not.toBeNull();
35	    expect(result?.choices[0].delta.content).toBe("Let me think...");
36	  });
37	
38	  test("converts tool-call to chat chunk", () => {
39	    const part: VercelStreamPart = {
40	      type: "tool-call",
41	      toolCallId: "call_abc123",
42	      toolName: "readFile",
43	      args: { filepath: "/path/to/file" },
44	    };
45	
46	    const result = convertVercelStreamPart(part, options);
47	
48	    expect(result).not.toBeNull();
49	    expect(result?.choices[0].delta.tool_calls).toHaveLength(1);
