52	      id: "call_abc123",
53	      type: "function",
54	      function: {
55	        name: "readFile",
56	        arguments: JSON.stringify({ filepath: "/path/to/file" }),
57	      },
58	    });
59	  });
60	
61	  test("converts tool-call-delta to chat chunk", () => {
